#!/usr/bin/env node
// PreToolUse Claude Code hook for Bash (matcher "Bash"): a human gate on bench commands and a hard
// stop on anything that would print site secrets.
//
// Why a hook on top of the permission rules in .claude/settings.json:
//   - Rules match the command text from the start. `bench --site * migrate` does not match
//     `bench --verbose --site test.localhost migrate`, `bench migrate` (default site from `bench use`),
//     `./env/bin/bench --site=test.localhost migrate`, or a bench call inside `su - frappe -c "..."`.
//     The hook tokenises the command, finds every bench invocation (also inside quoted strings)
//     and classifies its subcommand, so all of those spellings get the same decision.
//   - Rules cannot express "deny any command that names site_config.json".
//
// Decisions (JSON on stdout, exit 0; https://code.claude.com/docs/en/hooks, PreToolUse):
//   deny : prints or opens secrets (show-config, DB shells, site_config.json in any command,
//          execute of frappe.get_site_config / generate_keys), destroys or replaces data
//          (drop-site, reinstall, restore, trim-*), weakens access (set-password, add-system-manager,
//          browse, ngrok), or targets `--site all` with a write command.
//   ask  : changes schema, data or site config (migrate, console, execute, install-app, run-patch,
//          set-config, export-fixtures, backup, ...), run-tests on a site other than test.localhost,
//          bench-level changes (update, get-app, setup, new-site), and any unknown subcommand.
//   none : read-only or allow-listed commands (run-tests on test.localhost, list-apps, version, ...),
//          so the normal permission rules decide.
// Exit 2 only when the hook input cannot be parsed (fail closed).
import { readFileSync, realpathSync } from "node:fs";
import { pathToFileURL } from "node:url";

export const TEST_SITE = "test.localhost";

const DENY = {
  "show-config": "prints site_config.json (db_password, encryption_key) to stdout",
  mariadb: "opens a database shell with the site's credentials",
  postgres: "opens a database shell with the site's credentials",
  "db-console": "opens a database shell with the site's credentials",
  jupyter: "starts a notebook server with full site access",
  "drop-site": "destroys a site and its database",
  reinstall: "wipes and reinstalls the site database",
  restore: "replaces the site database from a backup",
  "partial-restore": "overwrites tables from a backup",
  "trim-database": "drops tables",
  "trim-tables": "drops columns",
  "clear-log-table": "deletes audit and log rows",
  "transform-database": "changes table engines or row formats",
  "migrate-to": "moves the site to another host",
  "remove-from-installed-apps": "edits the installed-apps list without uninstalling",
  "set-admin-password": "changes the Administrator password",
  "set-password": "changes a user's password",
  "add-system-manager": "grants System Manager",
  "destroy-all-sessions": "logs every user out",
  browse: "creates a login session for a user",
  ngrok: "exposes the site on a public URL",
};
const ASK = {
  migrate: "applies DocType JSON, patches and fixtures to the site database",
  console: "opens an IPython shell that can read and write any document",
  execute: "runs arbitrary Python as Administrator and commits",
  "install-app": "installs an app (after_install, fixtures, schema) on the site",
  "uninstall-app": "removes an app and drops its DocType tables",
  "run-patch": "runs a data or schema patch",
  "set-config": "writes site_config.json",
  "reload-doc": "re-syncs a DocType from JSON",
  "reload-doctype": "re-syncs a DocType from JSON",
  "export-fixtures": "rewrites fixtures JSON from the site",
  "import-doc": "writes documents into the site",
  "data-import": "writes documents into the site",
  "bulk-rename": "renames documents",
  "add-user": "creates a user",
  "disable-user": "disables a user",
  "reset-perms": "resets DocType permissions to their defaults",
  "add-database-index": "changes the schema",
  "set-maintenance-mode": "takes the site offline",
  "enable-scheduler": "starts scheduled jobs",
  "disable-scheduler": "stops scheduled jobs",
  "trigger-scheduler-event": "runs scheduled jobs now",
  "purge-jobs": "deletes queued jobs",
  "clear-cache": "clears the site cache",
  "clear-website-cache": "clears the website cache",
  backup: "writes a full database dump (PHI) to disk",
  "export-csv": "exports documents (PHI) to a file",
  "export-json": "exports documents (PHI) to a file",
  "export-doc": "exports a document (PHI) to a file",
  "new-site": "creates a site and a database",
  "new-app": "creates an app",
  "make-app": "creates an app",
  "get-app": "downloads and installs third-party code",
  update: "pulls, migrates and rebuilds every app on the bench",
  setup: "rewrites bench, supervisor or nginx configuration",
  restart: "restarts bench processes",
  "remove-app": "removes an app from the bench",
  use: "changes the default site",
  "set-last-active-for-user": "writes user data",
  "create-rq-users": "writes redis ACL users",
  request: "sends a request as Administrator",
  "publish-realtime": "publishes a realtime event",
  "add-to-email-queue": "queues outbound email",
  "run-parallel-tests": "runs tests (commits test records)",
  "start-recording": "records every SQL query of the site",
  "stop-recording": "stops the SQL recorder",
  "rebuild-global-search": "rewrites the global search index",
  "build-search-index": "rewrites the search index",
};
const PASS = new Set([
  "list-apps", "version", "doctor", "show-pending-jobs", "describe-database-table", "ready-for-migration",
  "build", "watch", "serve", "worker", "schedule", "scheduler", "--version", "--help", "src", "find",
]);
// execute targets that read secrets or mint credentials: deny even though execute itself is "ask".
const EXECUTE_DENY = /(^|\.)(get_site_config|get_conf|get_common_site_config)$|^frappe\.conf\b|generate_keys$|\bget_decrypted_password$|\bset_encrypted_password$/;
const SECRET_FILE = /\b(common_)?site_config\.json\b/;
const WRAPPERS = new Set(["sudo", "env", "nice", "time", "timeout", "nohup", "flock", "xargs", "docker", "kubectl", "ssh", "command", "exec"]);
const WRITE_ON_ALL = new Set([...Object.keys(ASK), ...Object.keys(DENY), "run-tests"]);

// Minimal POSIX-ish tokenizer: quotes, backslash escapes, and the separators ; & | ( ) and newlines.
export function tokenize(cmd) {
  const out = [];
  let cur = "";
  let quoted = false;
  let q = null;
  const push = () => { if (cur !== "" || quoted) out.push({ t: cur, quoted }); cur = ""; quoted = false; };
  for (let i = 0; i < cmd.length; i++) {
    const ch = cmd[i];
    if (q) {
      if (ch === q) { q = null; continue; }
      if (ch === "\\" && q === '"' && i + 1 < cmd.length) { cur += cmd[++i]; continue; }
      cur += ch;
      continue;
    }
    if (ch === "'" || ch === '"') { q = ch; quoted = true; continue; }
    if (ch === "\\" && i + 1 < cmd.length) { cur += cmd[++i]; continue; }
    if (/\s/.test(ch)) { if (ch === "\n") { push(); out.push({ t: ";", sep: true }); } else push(); continue; }
    if (";&|()".includes(ch)) { push(); out.push({ t: ch, sep: true }); continue; }
    cur += ch;
  }
  push();
  return out;
}

// Find every bench invocation: [{site, sub, args}], including
// `su - frappe -c "cd ~/frappe-bench && bench --site x migrate"`.
export function findBenchCalls(cmd, depth = 0) {
  const toks = tokenize(cmd);
  const calls = [];
  let segStart = 0;
  for (let i = 0; i < toks.length; i++) {
    const tk = toks[i];
    if (tk.sep) { segStart = i + 1; continue; }
    // A quoted string handed to a shell runner (`su - frappe -c "..."`, `bash -lc '...'`, `eval "..."`,
    // `ssh host "..."`) is parsed again as a command. Other quoted arguments (grep patterns) are not.
    const runner = i > 0 && !toks[i - 1].sep && (/^(-[a-z]*c|eval)$/.test(toks[i - 1].t) || toks[segStart].t === "ssh");
    if (tk.quoted && runner && depth < 3) { calls.push(...findBenchCalls(tk.t, depth + 1)); continue; }
    const base = tk.t.split("/").pop();
    if (base !== "bench" || tk.quoted) continue;
    // bench counts when it is the command of its segment, or runs under a wrapper
    // (sudo -u frappe bench ..., docker compose exec backend bench ..., flock /tmp/x bench ...).
    let f = segStart;
    while (f < i && /^[A-Za-z_][A-Za-z0-9_]*=/.test(toks[f].t)) f++; // SITE=x bench ...
    if (i !== f && !WRAPPERS.has(toks[f].t.split("/").pop())) continue;
    let site = null;
    let sub = null;
    const args = [];
    let k = i + 1;
    for (; k < toks.length && !toks[k].sep; k++) {
      const a = toks[k].t;
      if (sub === null) {
        if (a === "--site" && k + 1 < toks.length && !toks[k + 1].sep) { site = toks[++k].t; continue; }
        if (a.startsWith("--site=")) { site = a.slice(7); continue; }
        if (a === "--version" || a === "--help") { sub = a; continue; }
        if (a.startsWith("-")) continue; // global flags such as --verbose, --profile, --force
        sub = a;
      } else args.push(a);
    }
    calls.push({ site, sub: sub || "(none)", args });
    i = k - 1;
  }
  return calls;
}

export function decide(input) {
  if (String(input.tool_name || "") !== "Bash") return null;
  const cmd = String(input.tool_input?.command || "");
  if (SECRET_FILE.test(cmd)) {
    return { permissionDecision: "deny", permissionDecisionReason: "guard-bench: the command names site_config.json / common_site_config.json, which hold db_password and encryption_key. Agents never read or print them (context/security/phi-and-secrets-policy.md). Ask a human to check the one key you need." };
  }
  const calls = findBenchCalls(cmd);
  if (!calls.length) return null;
  let ask = null;
  for (const c of calls) {
    const where = c.site ? ` --site ${c.site}` : " (default site)";
    const label = `bench${where} ${c.sub}`;
    if (DENY[c.sub]) return { permissionDecision: "deny", permissionDecisionReason: `guard-bench: \`${label}\` ${DENY[c.sub]}. A human runs it outside Claude Code (docs/governance/approval-gates.md, gate G6).` };
    if (c.site === "all" && WRITE_ON_ALL.has(c.sub)) return { permissionDecision: "deny", permissionDecisionReason: `guard-bench: \`${label}\` targets every site on the bench. Agents work on ${TEST_SITE} only; fleet-wide commands are run by a human.` };
    if (c.sub === "execute") {
      const target = c.args.find((a) => !a.startsWith("-")) || "";
      if (EXECUTE_DENY.test(target)) return { permissionDecision: "deny", permissionDecisionReason: `guard-bench: \`${label} ${target}\` reads secrets or issues API credentials. API keys are generated by a System Manager for a named integration user (docs/governance/secrets.md).` };
    }
    if (c.sub === "run-tests" || c.sub === "run-parallel-tests") {
      if (c.site !== TEST_SITE) ask ??= `guard-bench: \`${label}\` runs tests on a site other than ${TEST_SITE}. Frappe test runs commit test records (make_test_records), so a human confirms the target site.`;
      continue;
    }
    if (ASK[c.sub]) { ask ??= `guard-bench: \`${label}\` ${ASK[c.sub]}. Approve only if you asked for this on this site${c.site && c.site !== TEST_SITE ? " (NOT the test site)" : ""}.`; continue; }
    if (PASS.has(c.sub)) continue;
    ask ??= `guard-bench: unknown bench subcommand \`${c.sub}\`; a human decides (fail closed to ask).`;
  }
  return ask ? { permissionDecision: "ask", permissionDecisionReason: ask } : null;
}

if (process.argv[1] && import.meta.url === pathToFileURL(realpathSync(process.argv[1])).href) {
  let input;
  try {
    input = JSON.parse(readFileSync(0, "utf8") || "{}");
  } catch {
    process.stderr.write("guard-bench: could not parse hook input; blocking to be safe.\n");
    process.exit(2);
  }
  const d = decide(input);
  if (d) process.stdout.write(JSON.stringify({ hookSpecificOutput: { hookEventName: "PreToolUse", ...d } }) + "\n");
  process.exit(0);
}

#!/usr/bin/env node
// Runs guard-bench.mjs as a real hook process against sample PreToolUse payloads for Bash.
// Usage: node .claude/hooks/guard-bench.test.mjs
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const hook = join(dirname(fileURLToPath(import.meta.url)), "guard-bench.mjs");
const cases = [
  { name: "run-tests on the test site passes through", cmd: "bench --site test.localhost run-tests --app spice_lite", expect: null },
  { name: "run-tests module inside su -c passes through", cmd: "su - frappe -c \"source ~/.spice-lite-bench-env && cd /home/user/frappe-bench && bench --site test.localhost run-tests --module spice_lite.tests.test_fhir_api\"", expect: null },
  { name: "CI=1 run-tests on the test site passes through", cmd: "cd /home/user/frappe-bench && CI=1 bench --site test.localhost run-tests --app spice_lite", expect: null },
  { name: "list-apps passes through", cmd: "cd /home/user/frappe-bench && bench --site test.localhost list-apps", expect: null },
  { name: "non-bench command is ignored", cmd: "git diff --stat", expect: null },
  { name: "the word bench as an argument is ignored", cmd: "grep -rn 'bench migrate' docs/", expect: null },
  { name: "docker compose exec bench migrate asks", cmd: "docker compose exec backend bench --site frontend migrate", expect: "ask" },
  { name: "env-prefixed bench execute asks", cmd: "FRAPPE_SITE=test.localhost bench execute spice_lite.install.after_migrate", expect: "ask" },
  { name: "migrate asks", cmd: "bench --site test.localhost migrate", expect: "ask" },
  { name: "migrate with a global flag first still asks", cmd: "bench --verbose --site test.localhost migrate", expect: "ask" },
  { name: "migrate on the default site still asks", cmd: "bench migrate", expect: "ask" },
  { name: "--site= form and a path to bench still ask", cmd: "./env/bin/bench --site=test.localhost migrate --skip-failing", expect: "ask" },
  { name: "migrate hidden in su -c asks", cmd: "su - frappe -c \"cd /home/user/frappe-bench && bench --site test.localhost migrate\"", expect: "ask" },
  { name: "sudo -u frappe bench console asks", cmd: "sudo -u frappe bench --site test.localhost console", expect: "ask" },
  { name: "execute asks", cmd: "bench --site test.localhost execute spice_lite.demo.seed_demo", expect: "ask" },
  { name: "install-app asks", cmd: "bench --site test.localhost install-app spice_ke", expect: "ask" },
  { name: "run-tests on another site asks", cmd: "bench --site ke.spice.example run-tests --app spice_lite", expect: "ask" },
  { name: "unknown subcommand fails closed to ask", cmd: "bench --site test.localhost frobnicate", expect: "ask" },
  { name: "show-config is denied", cmd: "bench --site test.localhost show-config", expect: "deny" },
  { name: "DB shell is denied", cmd: "bench --site test.localhost postgres", expect: "deny" },
  { name: "reading site_config.json through the shell is denied", cmd: "cat /home/user/frappe-bench/sites/test.localhost/site_config.json | jq .db_name", expect: "deny" },
  { name: "execute of get_site_config is denied", cmd: "bench --site test.localhost execute frappe.get_site_config", expect: "deny" },
  { name: "execute of generate_keys is denied", cmd: "bench --site test.localhost execute frappe.core.doctype.user.user.generate_keys --args \"['integration.erpnext@spice.example']\"", expect: "deny" },
  { name: "drop-site is denied", cmd: "bench drop-site test.localhost --force", expect: "deny" },
  { name: "--site all with migrate is denied", cmd: "bench --site all migrate", expect: "deny" },
  { name: "deny wins over ask in a compound command", cmd: "bench --site test.localhost migrate && bench --site test.localhost set-admin-password x", expect: "deny" },
  { name: "non-Bash tool is ignored", tool: "Read", cmd: "bench --site test.localhost show-config", expect: null },
];

let failed = 0;
for (const c of cases) {
  const payload = JSON.stringify({ session_id: "test", hook_event_name: "PreToolUse", tool_name: c.tool || "Bash", tool_input: { command: c.cmd, description: "test" }, tool_use_id: "toolu_test", cwd: process.cwd(), permission_mode: "default" });
  const r = spawnSync(process.execPath, [hook], { input: payload, encoding: "utf8" });
  let decision = null;
  let reason = "";
  if (r.stdout.trim()) {
    const out = JSON.parse(r.stdout);
    decision = out.hookSpecificOutput?.permissionDecision ?? null;
    reason = out.hookSpecificOutput?.permissionDecisionReason ?? "";
    if (out.hookSpecificOutput?.hookEventName !== "PreToolUse") decision = "BAD-EVENT-NAME";
  }
  const ok = r.status === 0 && decision === c.expect;
  if (!ok) failed++;
  console.log(`${ok ? "PASS" : "FAIL"}  ${c.name} (decision ${decision ?? "none"}, expected ${c.expect ?? "none"})${!ok && reason ? "  reason: " + reason : ""}`);
}
const bad = spawnSync(process.execPath, [hook], { input: "not json", encoding: "utf8" });
const badOk = bad.status === 2;
if (!badOk) failed++;
console.log(`${badOk ? "PASS" : "FAIL"}  unparseable input blocks with exit 2 (exit ${bad.status})`);
console.log(`\n${cases.length + 1 - failed}/${cases.length + 1} passed`);
process.exit(failed ? 1 : 0);

{
  "permissions": {
    "deny": [
      "Read(**/site_config.json)",
      "Read(**/common_site_config.json)",
      "Read(./.env)",
      "Read(./.env.*)",
      "Read(./**/*.phi.*)",
      "Read(~/.ssh/**)",
      "Bash(cat *site_config.json*)",
      "Bash(bench --site * show-config)",
      "Bash(bench --site * show-config *)",
      "Bash(bench --site * mariadb)",
      "Bash(bench --site * postgres)",
      "Bash(bench --site * db-console)",
      "Bash(bench drop-site *)",
      "Bash(bench --site * reinstall *)",
      "Bash(bench --site * restore *)",
      "Bash(bench --site all *)",
      "Bash(git push --force *)",
      "Bash(gh pr merge *)",
      "mcp__github__merge_pull_request"
    ],
    "ask": [
      "Bash(bench --site * migrate)",
      "Bash(bench --site * migrate *)",
      "Bash(bench --site * console)",
      "Bash(bench --site * execute *)",
      "Bash(git push *)"
    ],
    "disableBypassPermissionsMode": "disable"
  },
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          { "type": "command", "command": "node /etc/claude-code/hooks/guard-bench.mjs", "timeout": 10 }
        ]
      },
      {
        "matcher": "mcp__.*",
        "hooks": [
          { "type": "command", "command": "node /etc/claude-code/hooks/guard-outbound.mjs", "timeout": 10 }
        ]
      }
    ]
  }
}

#!/usr/bin/env node
// Human gate for two kinds of change that an agent can produce but must never merge on its own:
//   ai-config : the AI configuration of this repo (agents, skills, Claude Code hooks, settings,
//               MCP servers, CLAUDE.md, the skill library, the company-ai plugin, this gate).
//   schema    : Frappe schema and site-level behaviour (DocType JSON and controllers under
//               **/doctype/**, patches.txt and patch modules, hooks.py, fixtures, modules.txt).
// Used by docs/governance/ai-change-gate.yml.example as a required status check. For EACH category
// the PR touches, it needs an APPROVED review on the current head commit from a human who is not the
// PR author and (if that category's approver list is set) is on that list. One reviewer on both
// lists satisfies both categories.
//
// Usage:
//   node scripts/governance/check-ai-change-approval.mjs \
//     --changed changed.txt --reviews reviews.json --author alice --head-sha <sha> \
//     [--ai-approvers bob,carol] [--schema-approvers dan,erin]
//   changed.txt : one path per line (from GET /repos/{o}/{r}/pulls/{n}/files)
//   reviews.json: a JSON array or one JSON object per line, each {user, state, commit_id}
//                 (user may be a login string or {login}).
//   Approver lists default to the env vars AI_GOVERNANCE_APPROVERS and SCHEMA_APPROVERS.
// Exit 0 = gate satisfied, 1 = human approval missing, 2 = usage error.
import { readFileSync } from "node:fs";

// Paths are matched after stripping an optional leading "AI-SDLC-frappe/" so the gate works whether
// AI-SDLC-frappe is the repository root or a folder inside it.
export const GOVERNED = [
  // AI configuration
  [/(^|\/)\.claude\//, "ai-config", "Claude Code config (.claude/**)"],
  [/^\.mcp\.json$/, "ai-config", "MCP servers (.mcp.json)"],
  [/(^|\/)CLAUDE(\.local)?\.md$/, "ai-config", "project memory (CLAUDE.md)"],
  [/^skills\//, "ai-config", "skill library (skills/**)"],
  [/^company-ai\//, "ai-config", "company-ai plugin (company-ai/**)"],
  [/(^|\/)\.claude-plugin\//, "ai-config", "plugin manifest (.claude-plugin/**)"],
  [/^agents\/.+\/CONTRACT\.md$/, "ai-config", "Agent Contracts (agents/*/CONTRACT.md)"],
  [/^scripts\/governance\//, "ai-config", "governance scripts (scripts/governance/**)"],
  [/^\.github\/(workflows\/ai-change-gate\.yml|CODEOWNERS)$/, "ai-config", "the gate itself"],
  // Frappe schema and site behaviour
  [/(^|\/)doctype\/.+/, "schema", "DocType definition or controller (**/doctype/**)"],
  [/(^|\/)patches\.txt$/, "schema", "patch list (patches.txt)"],
  [/(^|\/)patches\/.+\.py$/, "schema", "patch module (patches/**)"],
  [/(^|\/)hooks\.py$/, "schema", "Frappe hooks (hooks.py)"],
  [/(^|\/)fixtures\/.+\.json$/, "schema", "fixtures (Custom Field, Property Setter, Role, ...)"],
  [/(^|\/)modules\.txt$/, "schema", "module list (modules.txt)"],
];

export const CATEGORY_LABEL = { "ai-config": "AI agent configuration", schema: "Frappe schema / hooks.py / patches / fixtures" };

export function governedChanges(paths) {
  const out = [];
  for (const raw of paths) {
    const p = raw.trim().replace(/^AI-SDLC-frappe\//, "");
    if (!p) continue;
    const hit = GOVERNED.find(([re]) => re.test(p));
    if (hit) out.push({ path: raw.trim(), category: hit[1], why: hit[2] });
  }
  return out;
}

export function parseReviews(text) {
  const t = text.trim();
  if (!t) return [];
  if (t.startsWith("[")) return JSON.parse(t);
  return t.split("\n").filter(Boolean).map((l) => JSON.parse(l));
}

const toSet = (list) => new Set((list || []).map((a) => a.trim().toLowerCase()).filter(Boolean));

export function evaluateGate({ changed, reviews, author, headSha, approvers = {} }) {
  const governed = governedChanges(changed);
  if (!governed.length) return { ok: true, governed, message: "No governed paths changed (AI config or Frappe schema); gate not required." };
  // GitHub returns reviews oldest first; the latest non-comment review per user is the one that counts.
  const latest = new Map();
  for (const r of reviews) {
    const login = typeof r.user === "string" ? r.user : r.user?.login;
    if (!login || r.state === "COMMENTED") continue;
    latest.set(login, r);
  }
  // A review is "valid" (a non-author human approval of the head commit) independent of category.
  const valid = [];
  const rejected = [];
  for (const [login, r] of latest) {
    const reasons = [];
    if (r.state !== "APPROVED") reasons.push(`latest review is ${r.state}`);
    if (login.toLowerCase() === String(author).toLowerCase()) reasons.push("is the PR author");
    if (/\[bot\]$/i.test(login)) reasons.push("is a bot");
    if (headSha && r.commit_id && r.commit_id !== headSha) reasons.push("approved an older commit");
    (reasons.length ? rejected : valid).push({ login, reasons });
  }
  const categories = [...new Set(governed.map((g) => g.category))];
  const lines = [];
  let ok = true;
  for (const cat of categories) {
    const allowed = toSet(approvers[cat]);
    const approvedBy = valid.filter((v) => !allowed.size || allowed.has(v.login.toLowerCase())).map((v) => v.login);
    const files = governed.filter((g) => g.category === cat).map((g) => `    - ${g.path} (${g.why})`).join("\n");
    if (approvedBy.length) {
      lines.push(`  [ok]      ${CATEGORY_LABEL[cat]}: approved by ${approvedBy.join(", ")}\n${files}`);
    } else {
      ok = false;
      const notListed = valid.filter((v) => allowed.size && !allowed.has(v.login.toLowerCase())).map((v) => `${v.login} (not on the ${cat} approver list)`);
      lines.push(`  [missing] ${CATEGORY_LABEL[cat]}: needs a non-author human approval on the head commit${allowed.size ? ` from one of: ${[...allowed].join(", ")}` : ""}${notListed.length ? `; does not count: ${notListed.join(", ")}` : ""}\n${files}`);
    }
  }
  const why = rejected.length ? "\nReviews that do not count:\n" + rejected.map((r) => `  - ${r.login}: ${r.reasons.join(", ")}`).join("\n") : "";
  const head = ok ? "Governed changes are approved:" : "Human approval required for governed changes:";
  const tail = ok ? "" : "\nAsk the owning group (see docs/governance/CODEOWNERS.example) to review and approve the current head commit.";
  return { ok, governed, message: `${head}\n${lines.join("\n")}${why}${tail}` };
}

function arg(name) {
  const i = process.argv.indexOf(`--${name}`);
  return i > 0 ? process.argv[i + 1] : undefined;
}

if (process.argv[1] && process.argv[1].endsWith("check-ai-change-approval.mjs")) {
  const changedFile = arg("changed");
  const reviewsFile = arg("reviews");
  if (!changedFile || !reviewsFile || !arg("author")) {
    console.error("usage: check-ai-change-approval.mjs --changed <file> --reviews <file> --author <login> [--head-sha <sha>] [--ai-approvers a,b] [--schema-approvers c,d]");
    process.exit(2);
  }
  const result = evaluateGate({
    changed: readFileSync(changedFile, "utf8").split("\n"),
    reviews: parseReviews(readFileSync(reviewsFile, "utf8")),
    author: arg("author"),
    headSha: arg("head-sha"),
    approvers: {
      "ai-config": (arg("ai-approvers") ?? process.env.AI_GOVERNANCE_APPROVERS ?? "").split(","),
      schema: (arg("schema-approvers") ?? process.env.SCHEMA_APPROVERS ?? "").split(","),
    },
  });
  console.log(`${result.ok ? "PASS" : "FAIL"}  ai-change-gate\n${result.message}`);
  process.exit(result.ok ? 0 : 1);
}

#!/usr/bin/env node
// Runs check-ai-change-approval.mjs as a CLI against fixture PRs.
// Usage: node scripts/governance/check-ai-change-approval.test.mjs
import { spawnSync } from "node:child_process";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const script = join(dirname(fileURLToPath(import.meta.url)), "check-ai-change-approval.mjs");
const dir = mkdtempSync(join(tmpdir(), "ai-gate-"));
const HEAD = "9f3c2e1";
const APP = "AI-SDLC-frappe/sample-app/spice_lite/spice_lite";
const cases = [
  { name: "API-only Python change needs no gate approval", changed: [`${APP}/api/fhir.py`, `${APP}/tests/test_fhir_api.py`], reviews: [], expect: 0 },
  { name: "agent change without review fails", changed: ["AI-SDLC-frappe/.claude/agents/developer.md"], reviews: [], expect: 1, grep: /\[missing\] AI agent configuration/ },
  { name: "author approving own PR does not count", changed: [".claude/settings.json"], reviews: [{ user: { login: "alice" }, state: "APPROVED", commit_id: HEAD }], expect: 1, grep: /alice: is the PR author/ },
  { name: "bot approval does not count", changed: [".claude/hooks/guard-bench.mjs"], reviews: [{ user: "github-actions[bot]", state: "APPROVED", commit_id: HEAD }], expect: 1, grep: /is a bot/ },
  { name: "approval of an older commit does not count", changed: ["AI-SDLC-frappe/.mcp.json"], reviews: [{ user: "bob", state: "APPROVED", commit_id: "1111111" }], expect: 1, grep: /approved an older commit/ },
  { name: "approval then changes requested by same reviewer fails", changed: ["AI-SDLC-frappe/skills/code-review/CHANGELOG.md"], reviews: [{ user: "bob", state: "APPROVED", commit_id: HEAD }, { user: "bob", state: "CHANGES_REQUESTED", commit_id: HEAD }], expect: 1, grep: /latest review is CHANGES_REQUESTED/ },
  { name: "DocType JSON change is governed as schema", changed: [`${APP}/clinical/doctype/sl_patient/sl_patient.json`], reviews: [], expect: 1, grep: /\[missing\] Frappe schema/ },
  { name: "patches.txt, patch module and hooks.py are schema", changed: [`${APP}/patches.txt`, `${APP}/patches/v0_2/add_national_id.py`, `${APP}/hooks.py`], reviews: [], expect: 1, grep: /patch list[\s\S]*patch module[\s\S]*Frappe hooks/ },
  { name: "country-app fixtures are schema", changed: ["apps/spice_ke/spice_ke/fixtures/custom_field.json"], reviews: [], expect: 1, grep: /fixtures \(Custom Field/ },
  { name: "schema approval passes when no list is configured", changed: [`${APP}/clinical/doctype/sl_observation/sl_observation.json`], reviews: [{ user: "bob", state: "APPROVED", commit_id: HEAD }], expect: 0, grep: /\[ok\]\s+Frappe schema.*bob/ },
  { name: "schema approver list is enforced separately from AI list", changed: [`${APP}/hooks.py`], reviews: [{ user: "carol", state: "APPROVED", commit_id: HEAD }], approvers: ["--ai-approvers", "bob,carol", "--schema-approvers", "dan,erin"], expect: 1, grep: /carol \(not on the schema approver list\)/ },
  { name: "mixed PR needs both groups", changed: [".claude/skills/code-review/SKILL.md", `${APP}/patches.txt`], reviews: [{ user: "carol", state: "APPROVED", commit_id: HEAD }], approvers: ["--ai-approvers", "bob,carol", "--schema-approvers", "dan,erin"], expect: 1, grep: /\[ok\]\s+AI agent configuration: approved by carol[\s\S]*\[missing\] Frappe schema/ },
  { name: "mixed PR passes with one approver from each group", changed: [".claude/skills/code-review/SKILL.md", `${APP}/patches.txt`], reviews: [{ user: "carol", state: "APPROVED", commit_id: HEAD }, { user: "dan", state: "APPROVED", commit_id: HEAD }], approvers: ["--ai-approvers", "bob,carol", "--schema-approvers", "dan,erin"], expect: 0 },
  { name: "changing the gate script itself is governed", changed: ["AI-SDLC-frappe/scripts/governance/check-ai-change-approval.mjs"], reviews: [], expect: 1 },
];

let failed = 0;
cases.forEach((c, i) => {
  const changed = join(dir, `changed-${i}.txt`);
  const reviews = join(dir, `reviews-${i}.json`);
  writeFileSync(changed, c.changed.join("\n") + "\n");
  // Alternate the two accepted review formats: JSON array and one object per line (gh --jq output).
  writeFileSync(reviews, i % 2 ? JSON.stringify(c.reviews) : c.reviews.map((r) => JSON.stringify(r)).join("\n"));
  const args = [script, "--changed", changed, "--reviews", reviews, "--author", "alice", "--head-sha", HEAD, ...(c.approvers || [])];
  const r = spawnSync(process.execPath, args, { encoding: "utf8", env: { ...process.env, AI_GOVERNANCE_APPROVERS: "", SCHEMA_APPROVERS: "" } });
  const ok = r.status === c.expect && (!c.grep || c.grep.test(r.stdout));
  if (!ok) failed++;
  console.log(`${ok ? "PASS" : "FAIL"}  ${c.name} (exit ${r.status}, expected ${c.expect})${ok ? "" : "\n" + r.stdout + r.stderr}`);
});
console.log(`\n${cases.length - failed}/${cases.length} passed`);
process.exit(failed ? 1 : 0);

