#!/usr/bin/env node
// Policy as code for the roster agents: model, effort, turn budget, tools and permission mode.
// Reads .claude/agents/*.md front matter and compares it with scripts/governance/agent-policy.json.
// Bench command scope (no console, migrate only via a human prompt) is enforced at runtime by
// .claude/hooks/guard-bench.mjs and the permission rules, not here: this checks the static contract.
//
// Usage: node scripts/governance/check-agent-policy.mjs [--agents-dir .claude/agents] [--policy <file>] [--strict]
// Exit 0 = no violations (missing roster files are warnings unless --strict), 1 = violations.
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { splitFrontmatter, toolList } from "./lib/frontmatter.mjs";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const arg = (n, d) => { const i = process.argv.indexOf(`--${n}`); return i > 0 ? process.argv[i + 1] : d; };
const agentsDir = resolve(arg("agents-dir", join(ROOT, ".claude/agents")));
const policy = JSON.parse(readFileSync(resolve(arg("policy", join(ROOT, "scripts/governance/agent-policy.json"))), "utf8"));
const STRICT = process.argv.includes("--strict");

// "claude-opus-5-5" -> "opus"; aliases pass through.
const family = (m) => (/opus/i.test(m) ? "opus" : /sonnet/i.test(m) ? "sonnet" : /haiku/i.test(m) ? "haiku" : /fable/i.test(m) ? "fable" : String(m));
const toolName = (t) => t.replace(/\(.*$/, "");

const errors = [];
const warnings = [];
const rows = [];
const files = existsSync(agentsDir) ? readdirSync(agentsDir).filter((f) => f.endsWith(".md")) : [];
const byName = new Map();
for (const f of files) {
  const { frontmatter } = splitFrontmatter(readFileSync(join(agentsDir, f), "utf8"));
  if (!frontmatter) { errors.push(`${f}: no YAML front matter`); continue; }
  byName.set(frontmatter.name || f.replace(/\.md$/, ""), { file: f, fm: frontmatter });
}

for (const [name, rule] of Object.entries(policy.agents)) {
  const entry = byName.get(name);
  if (!entry) { (STRICT ? errors : warnings).push(`${name}: .claude/agents/${name}.md not found (not written yet?)`); continue; }
  const { file, fm } = entry;
  const tag = `${file}`;
  for (const k of rule.requireFields || policy.global.requireFields) if (fm[k] === undefined || fm[k] === "") errors.push(`${tag}: missing required field "${k}"${k === "tools" ? " (omitted tools = inherits every tool, including MCP write tools)" : ""}`);
  const model = fm.model === undefined ? "" : String(fm.model);
  if (policy.global.forbiddenModels.includes(model)) errors.push(`${tag}: model "${model}" is not allowed (cost and behaviour must not depend on the caller's model)`);
  else if (model && !rule.models.includes(family(model))) errors.push(`${tag}: model "${model}" not in policy [${rule.models.join(", ")}]`);
  if (fm.effort !== undefined && !rule.effort.includes(String(fm.effort))) errors.push(`${tag}: effort "${fm.effort}" not in policy [${rule.effort.join(", ")}]`);
  if (fm.maxTurns !== undefined && !(Number(fm.maxTurns) > 0 && Number(fm.maxTurns) <= rule.maxTurns)) errors.push(`${tag}: maxTurns ${fm.maxTurns} exceeds policy ceiling ${rule.maxTurns}`);
  if (policy.global.forbiddenPermissionModes.includes(fm.permissionMode)) errors.push(`${tag}: permissionMode "${fm.permissionMode}" is forbidden`);
  const tools = toolList(fm.tools) || [];
  const names = tools.map(toolName);
  for (const t of rule.forbiddenTools) if (names.includes(t)) errors.push(`${tag}: tool "${t}" is forbidden for ${name}`);
  if (names.includes(policy.global.delegationTool) && !policy.global.delegationAllowedFor.includes(name)) {
    errors.push(`${tag}: "${policy.global.delegationTool}" in tools lets ${name} spawn subagents; the roster is flat (only ${policy.global.delegationAllowedFor.join(", ")} delegates)`);
  }
  rows.push([name, model || "-", String(fm.effort ?? "-"), String(fm.maxTurns ?? "-"), String(fm.permissionMode ?? "-"), names.join(" ") || "-"]);
}
for (const [name, { file }] of byName) if (!policy.agents[name]) warnings.push(`${file}: agent "${name}" has no policy entry (add it to agent-policy.json)`);

if (rows.length) {
  const head = ["agent", "model", "effort", "maxTurns", "permissionMode", "tools"];
  const w = head.map((h, i) => Math.max(h.length, ...rows.map((r) => r[i].length)));
  const fmt = (r) => r.map((c, i) => c.padEnd(w[i])).join("  ");
  console.log(fmt(head));
  for (const r of rows) console.log(fmt(r));
  console.log("");
}
for (const w of warnings) console.log(`WARN   ${w}`);
for (const e of errors) console.log(`ERROR  ${e}`);
console.log(`\n${rows.length}/${Object.keys(policy.agents).length} roster agents checked, ${errors.length} violation(s), ${warnings.length} warning(s)`);
process.exit(errors.length ? 1 : 0);

#!/usr/bin/env node
// Runs check-agent-policy.mjs against fixture agent folders. Usage: node scripts/governance/check-agent-policy.test.mjs
import { spawnSync } from "node:child_process";
import { mkdirSync, mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const script = join(dirname(fileURLToPath(import.meta.url)), "check-agent-policy.mjs");
const agent = (fm) => `---\n${fm}\n---\n\nYou are a test agent.\n`;
const good = {
  "reviewer.md": agent("name: reviewer\ndescription: Reviews diffs\ntools: Read, Grep, Glob, Bash\nmodel: sonnet\neffort: high\nmaxTurns: 25\npermissionMode: dontAsk"),
  "security.md": agent("name: security\ndescription: Security review\ntools: Read, Grep, Glob\nmodel: claude-opus-5-5\neffort: high\nmaxTurns: 30"),
};
const cases = [
  { name: "compliant agents pass", files: good, expect: 0, grep: /0 violation\(s\)/ },
  { name: "reviewer with Edit is a violation", files: { ...good, "reviewer.md": good["reviewer.md"].replace("tools: Read,", "tools: Read, Edit,") }, expect: 1, grep: /tool "Edit" is forbidden for reviewer/ },
  { name: "omitted tools is a violation", files: { ...good, "security.md": good["security.md"].replace("tools: Read, Grep, Glob\n", "") }, expect: 1, grep: /missing required field "tools"/ },
  { name: "model inherit is a violation", files: { ...good, "reviewer.md": good["reviewer.md"].replace("model: sonnet", "model: inherit") }, expect: 1, grep: /model "inherit" is not allowed/ },
  { name: "maxTurns above ceiling is a violation", files: { ...good, "reviewer.md": good["reviewer.md"].replace("maxTurns: 25", "maxTurns: 200") }, expect: 1, grep: /maxTurns 200 exceeds policy ceiling 25/ },
  { name: "bypassPermissions is a violation", files: { ...good, "security.md": good["security.md"].replace("maxTurns: 30", "maxTurns: 30\npermissionMode: bypassPermissions") }, expect: 1, grep: /permissionMode "bypassPermissions" is forbidden/ },
  { name: "non-orchestrator with Agent is a violation", files: { ...good, "reviewer.md": good["reviewer.md"].replace("Bash\n", "Bash, Agent\n") }, expect: 1, grep: /"Agent" in tools lets reviewer spawn subagents/ },
  { name: "missing roster file fails only with --strict", files: good, args: ["--strict"], expect: 1, grep: /architect: .*not found/ },
];

let failed = 0;
for (const c of cases) {
  const dir = mkdtempSync(join(tmpdir(), "agent-policy-"));
  mkdirSync(join(dir, "agents"));
  for (const [f, body] of Object.entries(c.files)) writeFileSync(join(dir, "agents", f), body);
  const r = spawnSync(process.execPath, [script, "--agents-dir", join(dir, "agents"), ...(c.args || [])], { encoding: "utf8" });
  const ok = r.status === c.expect && c.grep.test(r.stdout);
  if (!ok) failed++;
  console.log(`${ok ? "PASS" : "FAIL"}  ${c.name} (exit ${r.status}, expected ${c.expect})${ok ? "" : "\n" + r.stdout}`);
}
console.log(`\n${cases.length - failed}/${cases.length} passed`);
process.exit(failed ? 1 : 0);

#!/usr/bin/env node
// Aggregate the cost of a workflow run from saved `claude -p --output-format json` results and
// enforce a run-level budget.
//
// Each step of a headless run saves its result JSON (fields used: total_cost_usd, num_turns,
// subtype, is_error, duration_ms, session_id, modelUsage) as <run-dir>/costs/NN-<agent>.json:
//   claude -p "$PROMPT" --agent reviewer --max-turns 25 --max-budget-usd 2.00 \
//     --output-format json > .ai-sdlc/runs/$RUN_ID/costs/06-reviewer.json
//
// Usage: node scripts/governance/cost-report.mjs <run-dir>/costs [--budget-usd 10] [--json]
// Exit 0 = within budget and no step hit a limit, 1 = over budget or a step stopped on a limit,
// 2 = usage error. total_cost_usd is a client-side estimate; reconcile monthly with billing.
import { readdirSync, readFileSync } from "node:fs";
import { basename, join } from "node:path";

const dir = process.argv[2];
if (!dir || dir.startsWith("--")) {
  console.error("usage: cost-report.mjs <costs-dir> [--budget-usd N] [--json]");
  process.exit(2);
}
const i = process.argv.indexOf("--budget-usd");
const budget = i > 0 ? Number(process.argv[i + 1]) : null;
const LIMIT_SUBTYPES = new Set(["error_max_turns", "error_max_budget_usd"]);

const steps = [];
for (const f of readdirSync(dir).filter((x) => x.endsWith(".json")).sort()) {
  let r;
  try { r = JSON.parse(readFileSync(join(dir, f), "utf8")); } catch (e) { steps.push({ file: f, agent: "?", error: `invalid JSON: ${e.message}` }); continue; }
  const m = /^(\d+)-(.+)\.json$/.exec(basename(f));
  steps.push({
    file: f,
    step: m ? m[1] : "",
    agent: m ? m[2] : basename(f, ".json"),
    cost: Number(r.total_cost_usd ?? 0),
    turns: Number(r.num_turns ?? 0),
    subtype: String(r.subtype ?? "unknown"),
    isError: Boolean(r.is_error),
    seconds: r.duration_ms != null ? Math.round(Number(r.duration_ms) / 1000) : null,
    models: r.modelUsage && typeof r.modelUsage === "object" ? Object.keys(r.modelUsage) : [],
  });
}

const total = steps.reduce((s, x) => s + (x.cost || 0), 0);
const problems = [];
for (const s of steps) {
  if (s.error) problems.push(`${s.file}: ${s.error}`);
  else if (LIMIT_SUBTYPES.has(s.subtype)) problems.push(`${s.file}: stopped on a limit (${s.subtype}); output is partial, a human must decide whether to resume or re-plan`);
  else if (s.isError) problems.push(`${s.file}: is_error=true (subtype ${s.subtype})`);
}
if (budget != null && total > budget) problems.push(`run total $${total.toFixed(2)} exceeds budget $${budget.toFixed(2)}`);

if (process.argv.includes("--json")) {
  console.log(JSON.stringify({ total_cost_usd: Number(total.toFixed(4)), budget_usd: budget, steps, problems }, null, 2));
} else {
  const rows = steps.map((s) => [s.step, s.agent, s.error ? "-" : `$${s.cost.toFixed(2)}`, String(s.turns ?? "-"), s.subtype ?? "-", s.models.join(",") || "-"]);
  const head = ["step", "agent", "cost", "turns", "subtype", "models"];
  const w = head.map((h, k) => Math.max(h.length, ...rows.map((r) => r[k].length)));
  const fmt = (r) => r.map((c, k) => c.padEnd(w[k])).join("  ");
  console.log(fmt(head));
  for (const r of rows) console.log(fmt(r));
  const share = steps.filter((s) => s.cost).sort((a, b) => b.cost - a.cost)[0];
  console.log(`\nTotal: $${total.toFixed(2)}${budget != null ? ` of $${budget.toFixed(2)} budget (${Math.round((total / budget) * 100)}%)` : ""}`);
  if (share && total > 0) console.log(`Largest step: ${share.step}-${share.agent} ($${share.cost.toFixed(2)}, ${Math.round((share.cost / total) * 100)}% of run)`);
  for (const p of problems) console.log(`PROBLEM  ${p}`);
}
process.exit(problems.length ? 1 : 0);

